select to_jsonb(d) into v from catalog_work_descriptions d where work_id=1372 and language='en' for update;if v is distinct from '{"bound_author_id":924300157,"evidence":[{"checked_at":"2026-11-08T20:42:50Z","identity":"Work, author and exact English ISBN checked separately; synopsis concerns this novel.","secondary":null,"url":"https://www.hachette.co.uk/titles/pierce-brown/iron-gold/9781473646582/"}],"language":"en","provenance":"original_source_reviewed_summary","review_batch":"source-repair-20261108","review_status":"approved","reviewed_at":"2026-11-08T20:48:00+00:00","source_name":"Hachette UK / Hodder & Stoughton","source_type":"official_publisher","source_url":"https://www.hachette.co.uk/titles/pierce-brown/iron-gold/9781473646582/","text":"A decade after leading a revolution, Darrow still faces a war that refuses to end. The society he helped overturn has left a fragile new order, and another dangerous mission threatens everything he hoped to protect. Elsewhere, a young refugee, a grieving former soldier and an heir seeking revenge confront the consequences of that struggle. Their paths broaden the story beyond Darrow as the promises of liberation collide with the costs of continuing conflict.","work_id":1372}'::jsonb then raise exception 'Later summary modification';end if;
select to_jsonb(d) into v from catalog_work_descriptions d where work_id=4864 and language='en' for update;if v is distinct from '{"bound_author_id":2537,"evidence":[{"checked_at":"2026-11-08T20:42:50Z","identity":"Work, author and exact English ISBN checked separately; synopsis concerns this novel.","secondary":"https://catalog.wake.gov/Record/627298","url":"https://www.richlandlibrary.com/catalog/detail/1656511"}],"language":"en","provenance":"original_source_reviewed_summary","review_batch":"source-repair-20261108","review_status":"approved","reviewed_at":"2026-11-08T20:48:00+00:00","source_name":"Richland Library / Wake County Public Libraries","source_type":"official_catalog","source_url":"https://www.richlandlibrary.com/catalog/detail/1656511","text":"Lena has escaped a society that treats love as an illness, but freedom brings loss and unfamiliar dangers. Separated from Alex, she finds shelter among people resisting the authorities and begins to take part in their struggle. The second Delirium novel follows her efforts to survive beyond the world she knew and to find a place within the resistance. Her grief and new relationships complicate the choices she faces as that conflict draws her further in.","work_id":4864}'::jsonb then raise exception 'Later summary modification';end if;
select to_jsonb(w) into v from works w where id=1372 for update;if v is distinct from '{"author_id":924300157,"cover_id":null,"first_publish_year":2018,"id":1372,"native_identity_key":null,"open_library_id":"OL19726995W","source_type":"open_library","title":"Iron Gold","work_type":null}'::jsonb then raise exception 'Later parent modification';end if;
select to_jsonb(w) into v from works w where id=4864 for update;if v is distinct from '{"author_id":2537,"cover_id":null,"first_publish_year":2012,"id":4864,"native_identity_key":null,"open_library_id":"OL16286212W","source_type":null,"title":"Pandemonium","work_type":null}'::jsonb then raise exception 'Later parent modification';end if;
select to_jsonb(s) into v from catalog_description_snapshots s where work_id=4864 and edition_id=5023 and locale='en' for update;if v is distinct from '{"binding_hash":"9a33e9cf57aa0dfd912ac0ac311e34e12437ca17cbc7672a41461f17cbce4c57","bound_author_id":2537,"bound_isbn13":"9780061978067","bound_language":"eng","bound_open_library_work_id":"OL16286212W","bound_title":"Pandemonium","checked_at":"2026-11-08T20:49:45.311107+00:00","edition_id":5023,"fetched_at":"2026-11-08T20:02:54.647+00:00","locale":"en","provider_status":"withdrawn","source_key":"OL25104675M","text":null,"validation":"identity_and_language_verified","withdrawal_receipt_sha256":"b1822e4dfdb4b6cc26e8d13e30ecfe3c1aed8dbfe8f0242e0322805c2597209b","withdrawn_at":"2026-11-08T20:49:45.311107+00:00","withdrawn_text_sha256":"ec9a3438e1f89a20884c88913d64950bb324223762adec53fc82d74025c64765","work_id":4864}'::jsonb then raise exception 'Later source modification';end if;
delete from catalog_work_descriptions where work_id in(1372,4864) and language='en';
delete from catalog_description_snapshots where work_id=4864 and edition_id=5023 and locale='en';
update works set first_publish_year=1724 where id=4864;
insert into catalog_description_snapshots select * from jsonb_populate_record(null::catalog_description_snapshots,'{"work_id":4864,"edition_id":5023,"locale":"en","binding_hash":"9a33e9cf57aa0dfd912ac0ac311e34e12437ca17cbc7672a41461f17cbce4c57","bound_author_id":2537,"bound_title":"Pandemonium","bound_language":"eng","bound_isbn13":"9780061978067","bound_open_library_work_id":"OL16286212W","text":"In an alternate United States, love has been declared a dangerous disease, and the government forces everyone who reaches eighteen to have a procedure called the Cure. Living with her aunt, uncle, and cousins in Portland, Maine, Lena Haloway is very much looking forward to being cured and living a safe, predictable life. She watched love destroy her mother and isn''t about to make the same mistakes.\n\nBut with ninety-five days left until her treatment, Lena meets enigmatic Alex, a boy from the Wilds who lives under the government''s radar. What will happen if they do the unthinkable and fall in love?","source_key":"OL25104675M","fetched_at":"2026-11-08T20:02:54.647+00:00","checked_at":"2026-11-08T20:02:54.648+00:00","provider_status":"resolved","validation":"identity_and_language_verified"}'::jsonb);
end $$;commit;
